{"command":"python3 << 'PY' 2>&1 | head -n 400
import subprocess, threading, http.server, json, socket, time, os

class H(http.server.BaseHTTPRequestHandler):
    def do_GET(self):
        # record
        print("REQ", self.requestline, dict(self.headers), flush=True)
        if self.path=="/redirect":
            self.send_response(302); self.send_header("Location","/target"); self.end_headers(); return
        if self.path=="/target":
            body=b'{"target":1}'
        elif self.path=="/notfound":
            self.send_response(404); self.send_header("Content-Type","text/plain"); self.end_headers(); self.wfile.write(b'not json'); return
        elif self.path=="/errorjson":
            body=b'not json'
        elif self.path=="/status500":
            self.send_response(500); self.end_headers(); self.wfile.write(b'{"e":1}'); return
        else:
            body=b'{"hello":"world","path":"'+self.path.encode()+b'"}'
        self.send_response(200); self.send_header("Content-Type","application/json"); self.send_header("X-Test","yes"); self.end_headers(); self.wfile.write(body)
    def log_message(self,*a): pass

srv=http.server.ThreadingHTTPServer(("127.0.0.1",0), H)
port=srv.server_address[1]
print("port",port)
threading.Thread(target=srv.serve_forever, daemon=True).start()

def run(args, inp=b'', env=None):
    e=os.environ.copy()
    # clear proxy envs that might interfere
    for k in list(e):
        if "proxy" in k.lower(): del e[k]
    if env: e.update(env)
    p=subprocess.run(["./executable"]+args, input=inp, capture_output=True, env=e)
    return p.stdout, p.stderr, p.returncode

for path in ["/", "/target","/redirect","/notfound","/errorjson","/status500"]:
    o,e,c=run([f"http://127.0.0.1:{port}{path}"])
    print(path, o, e, c)

# also with query etc
o,e,c=run([f"http://user:pass@127.0.0.1:{port}/?a=1"])
print("userpass",o,e,c)
srv.shutdown()
PY"}

