func isTerminal(fd uintptr) bool {
	var termios syscall.Termios
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&termios)), 0, 0, 0)
	return errno == 0
}

func computeColor() bool {
	c := false
	if isTerminal(os.Stdout.Fd()) && os.Getenv("TERM") != "dumb" {
		c = true
	}
	if optMonochrome {
		c = false
	}
	if optColorize {
		c = true
	}
	if os.Getenv("NO_COLOR") != "" {
		c = false
	}
	return c
}

// ANSI colour helpers, in the style of a standard terminal aurora painter.
func paint(code, s, reset string) string {
	if !useColor {
		return s
	}
	return "\x1b[" + code + "m" + s + "\x1b[" + reset + "m"
}
func blueBold(s string) string { return paint("34;1", s, "0;22") }
func bold(s string) string {
	if !useColor {
		return s
	}
	return "\x1b[1m" + s + "\x1b[22m"
}
func magenta(s string) string { return paint("35", s, "0") }
func red(s string) string     { return paint("31", s, "0") }
func yellow(s string) string  { return paint("33", s, "0") }
func cyan(s string) string    { return paint("36", s, "0") }
func green(s string) string   { return paint("32", s, "0") }

// ---------------------------------------------------------------------------
// Identifiers

var reservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true,
	"const": true, "continue": true, "debugger": true, "default": true,
	"delete": true, "do": true, "else": true, "export": true,
	"extends": true, "false": true, "finally": true, "for": true,
	"function": true, "if": true, "import": true, "in": true,
	"instanceof": true, "new": true, "null": true, "return": true,
	"super": true, "switch": true, "this": true, "throw": true,
	"true": true, "try": true, "typeof": true, "var": true,
	"void": true, "while": true, "with": true, "yield": true,
}

func isIDStart(r rune) bool {
	return r == '_' || r == '$' ||
		unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl)
}
func isIDContinue(r rune) bool {
	return r == '_' || r == '$' ||
		unicode.In(r, unicode.Lu, unicode.Ll, unicode.Lm, unicode.Lo, unicode.Nl,
			unicode.Mn, unicode.Mc, unicode.Nd, unicode.Pc)
}

func validIdentifier(s string) bool {
	if s == "" || reservedWords[s] {
		return false
	}
	first := true
	for _, r := range s {
		if first {
			if !isIDStart(r) {
				return false
			}
			first = false
		} else if !isIDContinue(r) {
			return false
		}
	}
	return true
}

// ---------------------------------------------------------------------------
// Custom JSON-ish string encoding used by gron statements and the
// --json statement stream. Control characters (and a few others) are
// emitted as uppercase \uXXXX escapes; everything else is raw UTF-8.

func escapeString(s string) string {
	var b strings.Builder
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString(`\"`)
		case '\\':
			b.WriteString(`\\`)
		case '\b':
			b.WriteString(`\b`)
		case '\t':
			b.WriteString(`\t`)
		case '\n':
			b.WriteString(`\n`)
		case '\f':
			b.WriteString(`\f`)
		case '\r':
			b.WriteString(`\r`)
		default:
			if r < 0x20 || (r >= 0x7f && r <= 0x9f) || r == 0x2028 || r == 0x2029 {
				fmt.Fprintf(&b, `\u%04X`, r)
			} else {
				b.WriteRune(r)
			}
		}
	}
	return b.String()
}

func quoteString(s string) string { return `"` + escapeString(s) + `"` }

// ---------------------------------------------------------------------------
// Statements produced by flattening JSON (forward mode)

type fStatement struct {
	path  []interface{} // string or int elements
	value interface{}
}

func flatten(path []interface{}, value interface{}, out *[]fStatement) {
	var v interface{}
	switch value.(type) {
	case map[string]interface{}:
		v = map[string]interface{}{}
	case []interface{}:
		v = []interface{}{}
	default:
		v = value
	}
	p := make([]interface{}, len(path))
	copy(p, path)
	*out = append(*out, fStatement{path: p, value: v})
	switch t := value.(type) {
	case map[string]interface{}:
		for k, elem := range t {
			np := make([]interface{}, len(path)+1)
			copy(np, path)
			np[len(path)] = k
			flatten(np, elem, out)
		}
	case []interface{}:
		for i, elem := range t {
			np := make([]interface{}, len(path)+1)
			copy(np, path)
			np[len(path)] = i
			flatten(np, elem, out)
		}
	}
}

func sortSegment(e interface{}) string {
	switch t := e.(type) {
	case string:
		if validIdentifier(t) {
			return "." + t
		}
		return "[" + quoteString(t) + "]"
	case int:
		return "[" + strconv.Itoa(t) + "]"
	default:
		return fmt.Sprint(e)
	}
}

func statementLess(a, b fStatement) bool {
	n := len(a.path)
	if len(b.path) < n {
		n = len(b.path)
	}
	for i := 0; i < n; i++ {
		if a.path[i] == b.path[i] {
			continue
		}
		ai, aIsInt := a.path[i].(int)
		bi, bIsInt := b.path[i].(int)
		if aIsInt && bIsInt {
			return ai < bi
		}
		return sortSegment(a.path[i]) < sortSegment(b.path[i])
	}
	return len(a.path) < len(b.path)
}

func sortStatements(s []fStatement) {
	sort.SliceStable(s, func(i, j int) bool { return statementLess(s[i], s[j]) })
}

func coloredValue(v interface{}) string {
	switch t := v.(type) {
	case string:
		return yellow(quoteString(t))
	case json.Number:
		return red(t.String())
	case bool:
		return cyan(strconv.FormatBool(t))
	case nil:
		return cyan("null")
	case map[string]interface{}:
		return magenta("{}")
	case []interface{}:
		return magenta("[]")
	case int:
		return red(strconv.Itoa(t))
	case float64:
		b, _ := json.Marshal(t)
		return red(string(b))
	default:
		return fmt.Sprint(v)
	}
}

func (s fStatement) text() string {
	if optJSON {
		var b strings.Builder
		b.WriteString(magenta("["))
		b.WriteString(magenta("["))
		for i, e := range s.path {
			if i > 0 {
				b.WriteString(",")
			}
			switch t := e.(type) {
			case string:
				b.WriteString(yellow(quoteString(t)))
			case int:
				b.WriteString(red(strconv.Itoa(t)))
			}
		}
		b.WriteString(magenta("]"))
		b.WriteString(",")
		b.WriteString(coloredValue(s.value))
		b.WriteString(magenta("]"))
		return b.String()
	}
	var b strings.Builder
	b.WriteString(blueBold("json"))
	for _, e := range s.path {
		switch t := e.(type) {
		case string:
			if validIdentifier(t) {
				b.WriteString(".")
				b.WriteString(blueBold(t))
			} else {
				b.WriteString(magenta("["))
				b.WriteString(yellow(quoteString(t)))
				b.WriteString(magenta("]"))
			}
		case int:
			b.WriteString(magenta("["))
			b.WriteString(red(strconv.Itoa(t)))
			b.WriteString(magenta("]"))
		}
	}
	b.WriteString(" = ")
	b.WriteString(coloredValue(s.value))
	b.WriteString(";")
	return b.String()
}

// ---------------------------------------------------------------------------
// Input acquisition

func proxyForRequest(req *http.Request) (*url.URL, error) {
	pStr := ""
	if proxySet {
		pStr = optProxy
	} else if req.URL.Scheme == "https" {
		pStr = os.Getenv("https_proxy")
	} else {
		pStr = os.Getenv("http_proxy")
	}
	npStr := ""
	if noproxySet {
		npStr = optNoProxy
	} else {
		npStr = os.Getenv("no_proxy")
	}
	if npStr != "" {
		for _, h := range strings.Split(npStr, ",") {
			if h == req.URL.Host {
				return nil, nil
			}
		}
	}
	if pStr == "" {
		return nil, nil
	}
	u, err := url.Parse(pStr)
	if err != nil {
		return nil, nil
	}
	return u, nil
}

func getInput(name string) (io.ReadCloser, int) {
	if name == "" || name == "-" {
		return io.NopCloser(os.Stdin), 0
	}
	lower := strings.ToLower(name)
	if strings.HasPrefix(lower, "http://") || strings.HasPrefix(lower, "https://") {
		req, err := http.NewRequest("GET", name, nil)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return nil, 4
		}
		req.Header.Set("User-Agent", "gron/"+version)
		req.Header.Set("Accept", "application/json")
		tr := http.DefaultTransport.(*http.Transport).Clone()
		tr.Proxy = proxyForRequest
		tr.TLSClientConfig = &tls.Config{InsecureSkipVerify: optInsecure}
		client := &http.Client{Transport: tr, Timeout: 20 * time.Second}
		resp, err := client.Do(req)
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
			return nil, 4
		}
		return resp.Body, 0
	}
	f, err := os.Open(name)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return nil, 1
	}
	return f, 0
}

// ---------------------------------------------------------------------------
// Forward gron

func decodeJSON(r io.Reader) (interface{}, error) {
	dec := json.NewDecoder(r)
	dec.UseNumber()
	var v interface{}
	if err := dec.Decode(&v); err != nil {
		return nil, err
	}
	return v, nil
}

func gronForward(input io.Reader) int {
	v, err := decodeJSON(input)
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err)
		return 3
	}
	var stmts []fStatement
	flatten([]interface{}{}, v, &stmts)
	if !optNoSort {
		sortStatements(stmts)
	}
	for _, s := range stmts {
		fmt.Println(s.text())
	}
	return 0
}

func gronStream(input io.Reader) int {
	// The synthetic root of the stream.
	root := fStatement{path: []interface{}{}, value: []interface{}{}}
	fmt.Println(root.text())
	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 4096), 1024*1024)
	idx := 0
	for scanner.Scan() {
		line := scanner.Text()
		v, err := decodeJSON(strings.NewReader(line))
		if err != nil {
			fmt.Fprintf(os.Stderr, "failed to form statements: %s\n", err)
			return 3
		}
		var stmts []fStatement
		flatten([]interface{}{idx}, v, &stmts)
		if !optNoSort {
			sortStatements(stmts)
		}
		for _, s := range stmts {
			fmt.Println(s.text())
		}
		idx++
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "error reading multiline input: %s: %s\n", err)
		return 3
	}
	return 0
}

// ---------------------------------------------------------------------------
// Statement errors for ungron

const (
	errInvalidStatement = "invalid statement"
	errNoValue          = "statement has no value"
)

type stmtError struct {
	kind  string // "invalid", "novalue", "invalidvalue", "quotedkey", "intkey"
	stmt  string
	value string
}

func (e *stmtError) message() string {
	switch e.kind {
	case "invalid":
		return fmt.Sprintf("ungron failed for `%s`: %s", e.stmt, errInvalidStatement)
	case "novalue":
		return fmt.Sprintf("ungron failed for `%s`: %s", e.stmt, errNoValue)
	case "invalidvalue":
		return fmt.Sprintf("ungron failed for `%s`: invalid value `%s`", e.stmt, e.value)
	case "quotedkey":
		return fmt.Sprintf("ungron failed for `%s`: invalid quoted key `%s`", e.stmt, e.value)
	case "intkey":
		return fmt.Sprintf("ungron failed for `%s`: invalid integer key `%s`", e.stmt, e.value)
	}
	return e.kind
}

// ---------------------------------------------------------------------------
// Ungron statement representation and text statement parser

const (
	elemString = iota
	elemIndex
)

type pathElem struct {
	kind      int
	key       string // for elemString once resolved
	indexText string // for elemIndex (raw token text)
	index     int
	raw       string // raw segment as written / generated
	quotedRaw string // literal (including quotes) for bracket strings
	isQuoted  bool
}

const (
	valNone = iota
	valString
	valNumber
	valBool
	valNull
	valEmptyObject
	valEmptyArray
	valInvalid
)

type ungronStmt struct {
	elems        []pathElem
	rawValue     string
	valueKind    int
	value        interface{}
	invalidValue *string // segment for a deferred invalid-value error
}

func (s *ungronStmt) String() string {
	var b strings.Builder
	for _, e := range s.elems {
		b.WriteString(e.raw)
	}
	b.WriteString(" = ")
	b.WriteString(s.rawValue)
	b.WriteString(";")
	return b.String()
}

func (s *ungronStmt) pathString() string {
	var b strings.Builder
	for _, e := range s.elems {
		b.WriteString(e.raw)
	}
	return b.String()
}

type parsedLine struct {
	stmt      *ungronStmt
	err       *stmtError
	eqSeen    bool
	valuePos  int // index into line just past skipped value whitespace
	noStmt    bool
}

type lineParser struct {
	s     string
	pos   int
	elems []pathElem
}

func (p *lineParser) pathString() string {
	var b strings.Builder
	for _, e := range p.elems {
		b.WriteString(e.raw)
	}
	return b.String()
}

// scanStringLiteral scans a JSON string literal starting at p.s[start]
// (which must be '"'). It returns the index just past the closing quote,
// or -1 if unterminated.
func scanStringLiteral(s string, start int) int {
	for i := start + 1; i < len(s); {
		switch s[i] {
		case '\\':
			i += 2
			continue
		case '"':
			return i + 1
		}
		i++
	}
	return -1
}

func (p *lineParser) parseIdentifier() string {
	start := p.pos
	_, size := utf8.DecodeRuneInString(p.s[p.pos:])
	p.pos += size
	for p.pos < len(p.s) {
		r, size := utf8.DecodeRuneInString(p.s[p.pos:])
		if !isIDContinue(r) {
			break
		}
		p.pos += size
	}
	return p.s[start:p.pos]
}

// parseDot parses a '.' segment at p.pos. On failure it returns a stmtError.
func (p *lineParser) parseDot() *stmtError {
	// p.s[p.pos] == '.'
	p.pos++
	if p.pos >= len(p.s) {
		return &stmtError{kind: "invalid", stmt: p.pathString() + "."}
	}
	r, _ := utf8.DecodeRuneInString(p.s[p.pos:])
	if !isIDStart(r) {
		return &stmtError{kind: "invalid", stmt: p.pathString() + "."}
	}
	ident := p.parseIdentifier()
	p.elems = append(p.elems, pathElem{kind: elemString, key: ident, raw: "." + ident})
	return nil
}

func (p *lineParser) parseBracket() *stmtError {
	// p.s[p.pos] == '['
	start := p.pos
	p.pos++
	if p.pos >= len(p.s) {
		return &stmtError{kind: "invalid", stmt: p.pathString() + "["}
	}
	c := p.s[p.pos]
	if c == '"' {
		end := scanStringLiteral(p.s, p.pos)
		if end == -1 {
			return &stmtError{kind: "invalid", stmt: p.s}
		}
		lit := p.s[p.pos:end]
		if end >= len(p.s) || p.s[end] != ']' {
			return &stmtError{kind: "invalid", stmt: p.pathString() + "[" + lit}
		}
		p.elems = append(p.elems, pathElem{kind: elemString, raw: p.s[start : end+1], quotedRaw: lit, isQuoted: true})
		p.pos = end + 1
		return nil
	}
	if c >= '0' && c <= '9' {
		j := p.pos
		for j < len(p.s) && p.s[j] >= '0' && p.s[j] <= '9' {
			j++
		}
		digits := p.s[p.pos:j]
		if j >= len(p.s) || p.s[j] != ']' {
			return &stmtError{kind: "invalid", stmt: p.pathString() + "[" + digits}
		}
		p.elems = append(p.elems, pathElem{kind: elemIndex, indexText: digits, raw: p.s[start : j+1]})
		p.pos = j + 1
		return nil
	}
	return &stmtError{kind: "invalid", stmt: p.pathString() + "["}
}

// parseNumberToken scans a JSON number at s[start:]. It returns the
// token, its end index, and whether it is a valid JSON number.
func scanNumber(s string, start int) (string, int, bool) {
	i := start
	if i < len(s) && s[i] == '-' {
		i++
	}
	if i >= len(s) || s[i] < '0' || s[i] > '9' {
		return "", i, false
	}
	if s[i] == '0' {
		i++
	} else {
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	}
	if i < len(s) && s[i] == '.' {
		i++
		if i >= len(s) || s[i] < '0' || s[i] > '9' {
			return "", i, false
		}
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	}
	if i < len(s) && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i < len(s) && (s[i] == '+' || s[i] == '-') {
			i++
		}
		if i >= len(s) || s[i] < '0' || s[i] > '9' {
			return "", i, false
		}
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
	}
	return s[start:i], i, true
}

// keywordToken scans a true/false/null style token starting at
// s[start] (one of 't', 'f' or 'n'). Following the original tokeniser,
// characters after the first are consumed while they belong to the set
// of characters appearing in the remainder of the keyword.
func keywordToken(s string, start int) (tok string, target string, end int) {
	switch s[start] {
	case 't':
		target = "true"
	case 'f':
		target = "false"
	case 'n':
		target = "null"
	}
	allowed := map[byte]bool{}
	for i := 1; i < len(target); i++ {
		allowed[target[i]] = true
	}
	i := start + 1
	for i < len(s) && allowed[s[i]] {
		i++
	}
	return s[start:i], target, i
}

func parseTextLine(line string) parsedLine {
	res := parsedLine{valuePos: -1}
	if line == "" {
		res.noStmt = true
		return res
	}
	p := &lineParser{s: line}

	// Lines beginning with spaces only form a statement if the first
	// thing after the spaces is '=' (an empty, root, path).
	if line[0] == ' ' {
		i := 0
		for i < len(line) && line[i] == ' ' {
			i++
		}
		if i < len(line) && line[i] == '=' {
			p.pos = i
			return p.parseValue(&res)
		}
		res.noStmt = true
		return res
	}
	if line[0] == '=' {
		p.pos = 0
		return p.parseValue(&res)
	}

	// Parse the first path element.
	{
		c := line[0]
		switch {
		case c == '.':
			if err := p.parseDot(); err != nil {
				res.err = err
				return res
			}
		case c == '[':
			if err := p.parseBracket(); err != nil {
				res.err = err
				return res
			}
		default:
			r, _ := utf8.DecodeRuneInString(line)
			if !isIDStart(r) {
				res.err = &stmtError{kind: "invalid", stmt: ""}
				return res
			}
			ident := p.parseIdentifier()
			p.elems = append(p.elems, pathElem{kind: elemString, key: ident, raw: ident})
		}
	}

	singleBare := func() bool {
		return len(p.elems) == 1 && p.elems[0].raw == p.elems[0].key && !p.elems[0].isQuoted && p.elems[0].kind == elemString
	}

	// Parse any further path elements, up to '='.
	for p.pos < len(p.s) {
		c := p.s[p.pos]
		switch {
		case c == '.':
			if err := p.parseDot(); err != nil {
				res.err = err
				return res
			}
		case c == '[':
			if err := p.parseBracket(); err != nil {
				res.err = err
				return res
			}
		case c == '=':
			return p.parseValue(&res)
		case c == ';':
			res.err = &stmtError{kind: "invalid", stmt: p.pathString()}
			return res
		case c == ' ':
			if singleBare() {
				// Skip spaces; only '=' continues the statement.
				i := p.pos
				for i < len(p.s) && p.s[i] == ' ' {
					i++
				}
				if i < len(p.s) && p.s[i] == '=' {
					p.pos = i
					return p.parseValue(&res)
				}
				res.noStmt = true
				return res
			}
			i := p.pos
			for i < len(p.s) && p.s[i] == ' ' {
				i++
			}
			if i < len(p.s) && p.s[i] == '=' {
				p.pos = i
				return p.parseValue(&res)
			}
			res.err = &stmtError{kind: "novalue", stmt: p.pathString()}
			return res
		default:
			// A bare key directly following a bracket segment.
			prev := p.elems[len(p.elems)-1]
			isBracket := prev.raw != "" && prev.raw[0] == '['
			if isBracket {
				if r, _ := utf8.DecodeRuneInString(p.s[p.pos:]); isIDStart(r) {
					ident := p.parseIdentifier()
					p.elems = append(p.elems, pathElem{kind: elemString, key: ident, raw: ident})
					continue
				}
			}
			res.err = &stmtError{kind: "invalid", stmt: p.pathString()}
			return res
		}
	}

	// Ran out of input in the path.
	if singleBare() {
		res.noStmt = true
		return res
	}
	res.err = &stmtError{kind: "novalue", stmt: p.pathString()}
	return res
}

// parseValue is entered with p.pos at the '=' character.
func (p *lineParser) parseValue(res *parsedLine) parsedLine {
	res.eqSeen = true
	pathStr := p.pathString()
	eqPath := pathStr + " = "
	p.pos++ // consume '='

	// Skip the whitespace the original allows before a value.
	for p.pos < len(p.s) && (p.s[p.pos] == ' ' || p.s[p.pos] == '\t' || p.s[p.pos] == '\r') {
		p.pos++
	}
	res.valuePos = p.pos
	stmt := &ungronStmt{elems: p.elems, valueKind: valNone}
	res.stmt = stmt

	if p.pos >= len(p.s) {
		res.err = &stmtError{kind: "novalue", stmt: eqPath}
		return *res
	}
	// An immediate semicolon is an (invalid) empty value.
	if p.s[p.pos] == ';' {
		empty := ""
		stmt.invalidValue = &empty
		stmt.rawValue = ""
		return *res
	}

	start := p.pos
	c := p.s[p.pos]
	switch {
	case c == '"':
		end := scanStringLiteral(p.s, start)
		if end == -1 {
			res.err = &stmtError{kind: "novalue", stmt: eqPath + p.s[start:]}
			return *res
		}
		tok := p.s[start:end]
		stmt.rawValue = tok
		stmt.valueKind = valString
		// Only spaces may precede the terminating semicolon.
		i := end
		for i < len(p.s) && p.s[i] == ' ' {
			i++
		}
		if i < len(p.s) && p.s[i] == ';' {
			return *res
		}
		res.err = &stmtError{kind: "novalue", stmt: eqPath + tok}
		return *res
	case c == '{' || c == '[':
		close := byte('}')
		kind := valEmptyObject
		if c == '[' {
			close = ']'
			kind = valEmptyArray
		}
		_ = close
		if start+1 < len(p.s) && p.s[start+1] == close {
			tok := p.s[start : start+2]
			stmt.rawValue = tok
			stmt.valueKind = kind
			i := start + 2
			for i < len(p.s) && p.s[i] == ' ' {
				i++
			}
			if i < len(p.s) && p.s[i] == ';' {
				return *res
			}
			res.err = &stmtError{kind: "novalue", stmt: eqPath + tok}
			return *res
		}
		if start+1 < len(p.s) && p.s[start+1] == ';' {
			seg := string(c)
			stmt.invalidValue = &seg
			stmt.rawValue = seg
			return *res
		}
		res.err = &stmtError{kind: "novalue", stmt: eqPath + string(c)}
		return *res
	case (c >= '0' && c <= '9') || c == '-':
		tok, _, ok := scanNumber(p.s, start)
		if !ok {
			semi := strings.IndexByte(p.s[start:], ';')
			if semi == -1 {
				res.err = &stmtError{kind: "novalue", stmt: eqPath + p.s[start:]}
				return *res
			}
			seg := p.s[start : start+semi]
			stmt.invalidValue = &seg
			stmt.rawValue = seg
			return *res
		}
		stmt.rawValue = tok
		stmt.valueKind = valNumber
		if !strings.Contains(p.s[start:], ";") {
			res.err = &stmtError{kind: "novalue", stmt: eqPath + p.s[start:]}
			return *res
		}
		return *res
	case c == 't' || c == 'f' || c == 'n':
		tok, target, end := keywordToken(p.s, start)
		stmt.rawValue = tok
		// Immediate semicolon, or spaces then a semicolon.
		i := end
		if i < len(p.s) && p.s[i] == ';' {
			if tok == target {
				if c == 'n' {
					stmt.valueKind = valNull
				} else {
					stmt.valueKind = valBool
					stmt.value = tok == "true"
				}
			} else {
				seg := tok
				stmt.invalidValue = &seg
			}
			return *res
		}
		for i < len(p.s) && p.s[i] == ' ' {
			i++
		}
		if i < len(p.s) && p.s[i] == ';' {
			if tok == target {
				if c == 'n' {
					stmt.valueKind = valNull
				} else {
					stmt.valueKind = valBool
					stmt.value = tok == "true"
				}
			} else {
				seg := tok
				stmt.invalidValue = &seg
			}
			return *res
		}
		res.err = &stmtError{kind: "novalue", stmt: eqPath + tok}
		return *res
	default:
		semi := strings.IndexByte(p.s[start:], ';')
		if semi == -1 {
			res.err = &stmtError{kind: "novalue", stmt: eqPath + p.s[start:]}
			return *res
		}
		seg := p.s[start : start+semi]
		stmt.invalidValue = &seg
		stmt.rawValue = seg
		return *res
	}
}

// convertStmt resolves deferred conversion errors in the same order the
// original surfaces them (integer keys, then the value, then quoted
// keys) and fills in the statement's path keys and value.
func convertStmt(stmt *ungronStmt) *stmtError {
	for i, e := range stmt.elems {
		if e.kind == elemIndex {
			n, err := strconv.Atoi(e.indexText)
			if err != nil {
				return &stmtError{kind: "intkey", stmt: stmt.String(), value: e.indexText}
			}
			stmt.elems[i].index = n
		}
	}
	if stmt.invalidValue != nil {
		return &stmtError{kind: "invalidvalue", stmt: stmt.String(), value: *stmt.invalidValue}
	}
	switch stmt.valueKind {
	case valString:
		var s string
		if err := json.Unmarshal([]byte(stmt.rawValue), &s); err != nil {
			return &stmtError{kind: "invalidvalue", stmt: stmt.String(), value: stmt.rawValue}
		}
		stmt.value = s
	case valNumber:
		stmt.value = json.Number(stmt.rawValue)
	case valBool:
		// value already set by the parser
	case valNull:
		stmt.value = nil
	case valEmptyObject:
		stmt.value = map[string]interface{}{}
	case valEmptyArray:
		stmt.value = []interface{}{}
	}
	for i, e := range stmt.elems {
		if e.kind == elemString && e.isQuoted {
			var s string
			if err := json.Unmarshal([]byte(e.quotedRaw), &s); err != nil {
				return &stmtError{kind: "quotedkey", stmt: stmt.String(), value: e.quotedRaw}
			}
			stmt.elems[i].key = s
		}
	}
	return nil
}

// ---------------------------------------------------------------------------
// Building and merging ungron statements

func buildValue(elems []pathElem, value interface{}) interface{} {
	if len(elems) == 0 {
		return value
	}
	rest := buildValue(elems[1:], value)
	e := elems[0]
	if e.kind == elemString {
		return map[string]interface{}{e.key: rest}
	}
	out := make([]interface{}, e.index+1)
	out[e.index] = rest
	return out
}

func mergeValues(dst, src interface{}) (interface{}, error) {
	switch d := dst.(type) {
	case map[string]interface{}:
		s, ok := src.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot merge object with non-object")
		}
		for k, sv := range s {
			if dv, exists := d[k]; exists {
				m, err := mergeValues(dv, sv)
				if err != nil {
					return nil, err
				}
				d[k] = m
			} else {
				d[k] = sv
			}
		}
		return d, nil
	case []interface{}:
		s, ok := src.([]interface{})
		if !ok {
			return nil, fmt.Errorf("cannot merge array with non-array")
		}
		for len(d) < len(s) {
			d = append(d, nil)
		}
		for i, sv := range s {
			if sv == nil {
				continue
			}
			m, err := mergeValues(d[i], sv)
			if err != nil {
				return nil, err
			}
			d[i] = m
		}
		return d, nil
	default:
		return src, nil
	}
}

func statementsToValue(stmts []*ungronStmt) (interface{}, *stmtError, error) {
	// Building first; integer-key conversion errors surface before
	// merging errors for statements written in JSON form.
	built := make([]interface{}, 0, len(stmts))
	for _, stmt := range stmts {
		for i, e := range stmt.elems {
			if e.kind == elemIndex {
				n, err := strconv.Atoi(e.indexText)
				if err != nil {
					return nil, &stmtError{kind: "intkey", stmt: stmt.String(), value: e.indexText}, nil
				}
				stmt.elems[i].index = n
			}
		}
		built = append(built, buildValue(stmt.elems, stmt.value))
	}
	var result interface{}
	for i, b := range built {
		if i == 0 {
			result = b
			continue
		}
		m, err := mergeValues(result, b)
		if err != nil {
			return nil, nil, err
		}
		result = m
	}
	if m, ok := result.(map[string]interface{}); ok && len(m) == 1 {
		if v, exists := m["json"]; exists {
			result = v
		}
	}
	return result, nil, nil
}

func encodeUngronResult(result interface{}) int {
	if useColor {
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.SetEscapeHTML(false)
		if err := enc.Encode(result); err != nil {
			fmt.Fprintf(os.Stderr, "failed to encode JSON: %s\n", err)
			return 6
		}
		fmt.Println(colorizeJSON(buf.Bytes()))
		return 0
	}
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(result); err != nil {
		fmt.Fprintf(os.Stderr, "failed to encode JSON: %s\n", err)
		return 6
	}
	fmt.Fprint(os.Stdout, buf.String())
	return 0
}

// colorizeJSON tokenises JSON text and colours it, discarding
// whitespace between tokens.
func colorizeJSON(data []byte) string {
	s := string(data)
	var b strings.Builder
	type ctx struct{ object bool }
	var stack []ctx
	expectKey := false
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '{':
			b.WriteString(magenta("{"))
			stack = append(stack, ctx{object: true})
			expectKey = true
			i++
		case c == '[':
			b.WriteString(magenta("["))
			stack = append(stack, ctx{object: false})
			expectKey = false
			i++
		case c == '}' || c == ']':
			b.WriteString(magenta(string(c)))
			if len(stack) > 0 {
				stack = stack[:len(stack)-1]
			}
			expectKey = false
			i++
		case c == ':':
			b.WriteString(bold(":"))
			expectKey = false
			i++
		case c == ',':
			b.WriteString(bold(","))
			if len(stack) > 0 && stack[len(stack)-1].object {
				expectKey = true
			} else {
				expectKey = false
			}
			i++
		case c == '"':
			end := scanStringLiteral(s, i)
			if end == -1 {
				end = len(s)
			}
			inner := ""
			if end-1 >= i+1 {
				if end <= len(s) && end-1 >= i+1 {
					inner = s[i+1 : end-1]
				}
			}
			isKey := len(stack) > 0 && stack[len(stack)-1].object && expectKey
			if isKey {
				b.WriteString(blueBold(`"`))
				b.WriteString(blueBold(inner))
				b.WriteString(blueBold(`"`))
				expectKey = false
			} else {
				b.WriteString(green(`"`))
				b.WriteString(yellow(inner))
				b.WriteString(green(`"`))
			}
			i = end
		case (c >= '0' && c <= '9') || c == '-':
			_, end, _ := scanNumber(s, i)
			if end == i {
				end = i + 1
			}
			b.WriteString(red(s[i:end]))
			i = end
		case c >= 'a' && c <= 'z':
			j := i
			for j < len(s) && s[j] >= 'a' && s[j] <= 'z' {
				j++
			}
			b.WriteString(cyan(s[i:j]))
			i = j
		default:
			b.WriteByte(c)
			i++
		}
	}
	return b.String()
}

func ungronText(input io.Reader) int {
	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 4096), 1024*1024)
	var stmts []*ungronStmt
	for scanner.Scan() {
		line := scanner.Text()
		parsed := parseTextLine(line)
		if parsed.err != nil {
			fmt.Fprintln(os.Stderr, parsed.err.message())
			return 5
		}
		if parsed.noStmt || parsed.stmt == nil {
			continue
		}
		if cerr := convertStmt(parsed.stmt); cerr != nil {
			fmt.Fprintln(os.Stderr, cerr.message())
			return 5
		}
		stmts = append(stmts, parsed.stmt)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, "failed to read input statements")
		return 2
	}
	if len(stmts) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		return 5
	}
	result, serr, merr := statementsToValue(stmts)
	if serr != nil {
		fmt.Fprintln(os.Stderr, serr.message())
		return 5
	}
	if merr != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", merr)
		return 5
	}
	return encodeUngronResult(result)
}

func ungronJSON(input io.Reader) int {
	scanner := bufio.NewScanner(input)
	scanner.Buffer(make([]byte, 0, 4096), 1024*1024)
	var stmts []*ungronStmt
	for scanner.Scan() {
		line := scanner.Text()
		var raw []interface{}
		if err := json.Unmarshal([]byte(line), &raw); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 5
		}
		invalid := false
		var path []interface{}
		var value interface{}
		if len(raw) != 2 {
			invalid = true
		} else {
			var ok bool
			path, ok = raw[0].([]interface{})
			if !ok {
				invalid = true
			}
			value = raw[1]
		}
		if !invalid {
			for _, pe := range path {
				switch pe.(type) {
				case string, float64:
				default:
					invalid = true
				}
			}
			switch v := value.(type) {
			case map[string]interface{}:
				if len(v) != 0 {
					invalid = true
				}
			case []interface{}:
				if len(v) != 0 {
					invalid = true
				}
			}
		}
		if invalid {
			fmt.Fprintln(os.Stderr, "invalid JSON layout")
			return 5
		}
		stmt := &ungronStmt{value: value}
		stmt.elems = append(stmt.elems, pathElem{kind: elemString, key: "json", raw: "json"})
		for _, pe := range path {
			switch t := pe.(type) {
			case string:
				stmt.elems = append(stmt.elems, pathElem{kind: elemString, key: t, raw: "[" + quoteString(t) + "]"})
			case float64:
				b, _ := json.Marshal(t)
				stmt.elems = append(stmt.elems, pathElem{kind: elemIndex, indexText: string(b), raw: "[" + string(b) + "]"})
			}
		}
		vb, _ := json.Marshal(value)
		stmt.rawValue = string(vb)
		stmts = append(stmts, stmt)
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, "failed to read input statements")
		return 2
	}
	if len(stmts) == 0 {
		fmt.Fprintln(os.Stderr, "no statements were parsed")
		return 5
	}
	result, serr, merr := statementsToValue(stmts)
	if serr != nil {
		fmt.Fprintln(os.Stderr, serr.message())
		return 5
	}
	if merr != nil {
		fmt.Fprintf(os.Stderr, "failed to merge statements: %s\n", merr)
		return 5
	}
	return encodeUngronResult(result)
}

// ---------------------------------------------------------------------------
// Values mode

func panicEmptyValue() {
	var empty []string
	fmt.Print(empty[0])
}

func gronValues(input io.Reader) int {
	scanner := bufio.NewScanner(input)
	for scanner.Scan() {
		line := scanner.Text()
		parsed := parseTextLine(line)
		if !parsed.eqSeen {
			if line == "" || (len(line) > 0 && line[0] == ' ') {
				fmt.Fprintf(os.Stderr, "failed to parse '%s' as gron statement\n", line)
				return 5
			}
			if line == "json" || strings.HasPrefix(line, "json ") {
				panicEmptyValue()
			}
			continue
		}
		i := parsed.valuePos
		if i < 0 || i >= len(line) {
			fmt.Println("")
			continue
		}
		c := line[i]
		switch {
		case c == '"':
			end := scanStringLiteral(line, i)
			if end == -1 {
				continue
			}
			var s string
			if err := json.Unmarshal([]byte(line[i:end]), &s); err != nil {
				continue
			}
			fmt.Println(s)
		case c == '{' || c == '[':
			continue
		case c == 't' || c == 'f' || c == 'n':
			tok, _, _ := keywordToken(line, i)
			fmt.Println(tok)
		default:
			seg := line[i:]
			if idx := strings.IndexByte(seg, ';'); idx != -1 {
				seg = seg[:idx]
			}
			fmt.Println(seg)
		}
	}
	return 0
}

// ---------------------------------------------------------------------------

func main() {
	flag.Usage = func() {
		fmt.Fprint(flag.CommandLine.Output(), usageText)
	}
	flag.BoolVar(&optUngron, "u", false, "")
	flag.BoolVar(&optUngron, "ungron", false, "")
	flag.BoolVar(&optValues, "v", false, "")
	flag.BoolVar(&optValues, "values", false, "")
	flag.BoolVar(&optColorize, "c", false, "")
	flag.BoolVar(&optColorize, "colorize", false, "")
	flag.BoolVar(&optMonochrome, "m", false, "")
	flag.BoolVar(&optMonochrome, "monochrome", false, "")
	flag.BoolVar(&optStream, "s", false, "")
	flag.BoolVar(&optStream, "stream", false, "")
	flag.BoolVar(&optInsecure, "k", false, "")
	flag.BoolVar(&optInsecure, "insecure", false, "")
	flag.StringVar(&optProxy, "x", "", "")
	flag.StringVar(&optProxy, "proxy", "", "")
	flag.StringVar(&optNoProxy, "noproxy", "", "")
	flag.BoolVar(&optJSON, "j", false, "")
	flag.BoolVar(&optJSON, "json", false, "")
	flag.BoolVar(&optNoSort, "no-sort", false, "")
	flag.BoolVar(&optVersion, "version", false, "")
	flag.Parse()

	os.Exit(run())
}

func run() int {
	if optVersion {
		fmt.Fprintf(os.Stdout, "gron version %s\n", version)
		return 0
	}
	useColor = computeColor()
	flag.Visit(func(f *flag.Flag) {
		if f.Name == "x" || f.Name == "proxy" {
			proxySet = true
		}
		if f.Name == "noproxy" {
			noproxySet = true
		}
	})
	var name string
	if flag.NArg() > 0 {
		name = flag.Arg(0)
	}
	input, code := getInput(name)
	if code != 0 {
		return code
	}
	defer input.Close()
	if optUngron {
		if optJSON {
			return ungronJSON(input)
		}
		return ungronText(input)
	}
	if optValues {
		return gronValues(input)
	}
	if optStream {
		return gronStream(input)
	}
	return gronForward(input)
}
