            obj={}
            cps=[]
            for cp in range(base, min(base+5000,0x110000)):
                if 0xD800 <= cp <= 0xDFFF: continue
                ch=chr(cp)
                key=ch if which=='start' else 'a'+ch+'b'
                cps.append(cp); obj[key]=len(cps)-1
            inp=json.dumps(obj, ensure_ascii=False).encode()
            p=subprocess.run([bin], input=inp, capture_output=True)
            out=p.stdout.decode()
            bracket=set()
            for line in out.splitlines():
                if ' = ' not in line or line.startswith('json ='): continue
                lhs,rhs=line.rsplit(' = ',1)
                try: idx=int(rhs.rstrip(';'))
                except: continue
                if lhs.startswith('json["'): bracket.add(idx)
            for i,cp in enumerate(cps):
